CREATE TABLE result AS WITH q(qid,x,y,z) AS (VALUES(1,0,0,0),(2,1,1,1),(3,0,0,NULL),(4,0,NULL,0),(5,NULL,0,0),(6,1,1,NULL),(7,1,NULL,1),(8,NULL,1,1)) SELECT qid,1 AS opno,'IS' AS op,t.rowid AS rid FROM q LEFT JOIN t4 AS t ON t.a IS q.x AND t.b IS q.y AND t.c IS q.z UNION ALL SELECT qid,2,'==',t.rowid FROM q LEFT JOIN t4 AS t ON t.a==q.x AND t.b==q.y AND t.c==q.z UNION ALL SELECT qid,3,'<',t.rowid FROM q LEFT JOIN t4 AS t ON (t.a<q.x) OR (t.a==q.x AND t.b<q.y) OR (t.a==q.x AND t.b==q.y AND t.c<q.z) UNION ALL SELECT qid,4,'<=',t.rowid FROM q LEFT JOIN t4 AS t ON (t.a<q.x) OR (t.a==q.x AND t.b<q.y) OR (t.a==q.x AND t.b==q.y AND t.c<=q.z) UNION ALL SELECT qid,5,'>',t.rowid FROM q LEFT JOIN t4 AS t ON (t.a>q.x) OR (t.a==q.x AND t.b>q.y) OR (t.a==q.x AND t.b==q.y AND t.c>q.z) UNION ALL SELECT qid,6,'>=',t.rowid FROM q LEFT JOIN t4 AS t ON (t.a>q.x) OR (t.a==q.x AND t.b>q.y) OR (t.a==q.x AND t.b==q.y AND t.c>=q.z);